const articles: Article[] = [
  { id: 1, category: 'Instituições', title: 'Como funciona o Congresso Nacional?', description: 'Entenda as funções da Câmara, do Senado e como um projeto pode virar lei.', readTime: '8 min', icon: 'landmark',
    content: ['O Congresso Nacional é formado por duas Casas: a Câmara dos Deputados e o Senado Federal. Juntas, elas exercem funções legislativas e fiscalizam atos do Poder Executivo, dentro das competências previstas na Constituição.', 'A Câmara representa a população e tem número de deputados por estado proporcional à população, respeitados os limites constitucionais. O Senado representa os estados e o Distrito Federal, com três senadores por unidade da Federação.', 'Em regra, um projeto precisa ser discutido e votado nas Casas competentes. O percurso depende do tipo de proposta: projetos de lei, propostas de emenda à Constituição e medidas provisórias seguem procedimentos diferentes. Após aprovação, pode haver sanção ou veto presidencial, conforme o caso.', 'Para avaliar uma notícia sobre votação, procure o número da proposição, a comissão responsável, o texto aprovado e a etapa atual. Uma aprovação em comissão, por exemplo, não significa necessariamente que uma proposta já virou lei.'],
    sources: [{ label: 'Câmara dos Deputados', url: 'https://www.camara.leg.br/' }, { label: 'Senado Federal', url: 'https://www12.senado.leg.br/' }, { label: 'Constituição Federal — Planalto', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }] },
  { id: 2, category: 'Ideologias', title: 'Conservadorismo e liberalismo: diferenças', description: 'Conheça as origens, princípios e diferenças entre correntes políticas.', readTime: '10 min', icon: 'scale',
    content: ['Conservadorismo e liberalismo são tradições amplas, com diferentes correntes internas. Seus significados variam conforme o país, a época e o autor; por isso, convém evitar tratar qualquer uma delas como um bloco único.', 'O conservadorismo costuma enfatizar continuidade institucional, prudência diante de mudanças rápidas, tradições e vínculos comunitários. Há conservadores que defendem mercados livres e outros que apoiam maior intervenção econômica em determinadas áreas.', 'O liberalismo dá destaque, em diferentes versões, às liberdades individuais, ao Estado de Direito e à limitação do poder. O liberalismo clássico tende a defender mercados e governo limitado; correntes sociais ou igualitárias podem aceitar políticas públicas mais amplas para ampliar oportunidades.', 'Na prática, partidos e políticos combinam ideias de maneiras distintas. Para entender uma posição, examine propostas concretas — por exemplo, sobre impostos, costumes, direitos civis e serviços públicos — em vez de concluir apenas pelo rótulo ideológico.'],
    sources: [{ label: 'Stanford Encyclopedia of Philosophy — Liberalism', url: 'https://plato.stanford.edu/entries/liberalism/' }, { label: 'Stanford Encyclopedia of Philosophy — Conservatism', url: 'https://plato.stanford.edu/entries/conservatism/' }] },
  { id: 3, category: 'Economia', title: 'Inflação, juros e poder de compra', description: 'Um guia introdutório para compreender indicadores econômicos do dia a dia.', readTime: '7 min', icon: 'economy',
    content: ['Inflação é o aumento generalizado dos preços ao longo do tempo. Quando os preços sobem, uma mesma quantia de dinheiro tende a comprar menos bens e serviços. A inflação de um índice não significa que todos os preços mudaram na mesma proporção.', 'No Brasil, o IPCA é o índice oficial de inflação ao consumidor utilizado como referência pelo regime de metas. O IBGE divulga os resultados e a metodologia. A experiência de cada família pode ser diferente da média do índice, pois depende de sua cesta de consumo.', 'A taxa Selic é a taxa básica de juros definida pelo Comitê de Política Monetária do Banco Central. Ela influencia o custo do crédito e as condições financeiras, mas não determina sozinha todos os juros cobrados. Os efeitos sobre inflação e atividade econômica ocorrem com defasagens e dependem de vários fatores.', 'Ao analisar uma afirmação econômica, confira período, unidade, série histórica e fonte. Dizer que a inflação caiu pode significar que os preços continuam subindo, mas em ritmo menor; não significa necessariamente que os preços diminuíram.'],
    sources: [{ label: 'IBGE — Inflação', url: 'https://www.ibge.gov.br/explica/inflacao.php' }, { label: 'Banco Central do Brasil', url: 'https://www.bcb.gov.br/' }] },
  { id: 4, category: 'História', title: 'Redemocratização brasileira', description: 'Os acontecimentos e as instituições que marcaram a transição democrática.', readTime: '12 min', icon: 'history',
    content: ['A redemocratização brasileira foi um processo político gradual que encerrou o regime militar instaurado em 1964 e restabeleceu instituições democráticas. O processo envolveu mobilização social, negociações políticas, mudanças legais e disputas sobre o ritmo da transição.', 'Entre os marcos estão a campanha das Diretas Já, a eleição indireta de Tancredo Neves em 1985, a posse de José Sarney após a doença e morte de Tancredo e a Assembleia Nacional Constituinte, que elaborou a Constituição promulgada em 1988.', 'A Constituição de 1988 estabeleceu direitos e garantias fundamentais, organizou os Poderes e definiu regras para a Federação. Ela é frequentemente chamada de Constituição Cidadã por sua ênfase em direitos, participação e políticas sociais.', 'Historiadores podem divergir sobre causas, protagonistas e consequências do processo. Ao estudar o período, compare documentos, pesquisas acadêmicas, depoimentos e cronologias, distinguindo fatos documentados de interpretações históricas.'],
    sources: [{ label: 'Arquivo Nacional', url: 'https://www.gov.br/arquivonacional/pt-br' }, { label: 'Constituição Federal — Planalto', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }] },
  { id: 5, category: 'Instituições', title: 'O que faz o STF?', description: 'Competências, limites e como funciona o controle de constitucionalidade.', readTime: '9 min', icon: 'landmark',
    content: ['O Supremo Tribunal Federal é o órgão de cúpula do Poder Judiciário brasileiro e tem, entre suas funções, a guarda da Constituição. Sua competência está definida principalmente no artigo 102 da Constituição Federal.', 'O STF julga determinados processos originariamente e analisa recursos em hipóteses constitucionais. No controle de constitucionalidade, pode avaliar se leis ou atos normativos são compatíveis com a Constituição, por meio de instrumentos processuais específicos.', 'O Tribunal não substitui todos os demais órgãos do Judiciário: a competência depende do tipo de processo e das regras constitucionais. Decisões judiciais também devem ser lidas em seu contexto, incluindo a questão julgada, os fundamentos e os efeitos definidos.', 'Para pesquisar uma decisão, consulte o número do processo, o acórdão, a data, o relator e a situação processual. Manchetes resumidas podem omitir limites importantes da decisão.'],
    sources: [{ label: 'Supremo Tribunal Federal', url: 'https://portal.stf.jus.br/' }, { label: 'Constituição Federal — Planalto', url: 'https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm' }] },
  { id: 6, category: 'Método', title: 'Como verificar uma afirmação política', description: 'Um roteiro para checar dados, localizar a fonte original e avaliar contexto.', readTime: '6 min', icon: 'scale',
    content: ['Comece registrando a afirmação exata e identificando quem a fez, quando e em qual contexto. Frases recortadas podem perder ressalvas ou se referir a períodos diferentes do que a publicação sugere.', 'Procure a fonte original: um projeto de lei, uma tabela estatística, um discurso completo, uma decisão ou um relatório. Se a publicação citar um número, verifique a unidade, a população, o período e a metodologia.', 'Compare fontes independentes e confiáveis. Uma fonte primária ajuda a confirmar o que foi publicado, mas pode não responder sozinha se a interpretação feita sobre ela é correta. Para isso, pode ser necessário consultar especialistas e estudos metodológicos.', 'Ao concluir, classifique o que encontrou: confirmado, incorreto, impreciso, fora de contexto ou ainda inconclusivo. É melhor admitir que faltam dados do que preencher lacunas com suposições.'],
    sources: [{ label: 'Agência Senado', url: 'https://www12.senado.leg.br/noticias' }, { label: 'IBGE', url: 'https://www.ibge.gov.br/' }, { label: 'Portal da Câmara', url: 'https://www.camara.leg.br/' }] },
]

